-- 追加の網羅性監査(第3ラウンド): category 2(探索・推論)で0件だったA*探索、
-- 前向き推論/後ろ向き推論(IF-THENルールに基づくエキスパートシステムの推論方式)を追加。
-- インスタンスセグメンテーション・GoogLeNet等は既に十分な言及があり見送り。
BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('g-kentei-q60', '2. 人工知能をめぐる動向',
   'スタートからの実際のコスト（移動距離など）と、ゴールまでの推定コスト（ヒューリスティック関数）の両方を使って、効率よく最短経路を探す探索アルゴリズムはどれか。',
   NULL::text,
   '["A*探索","幅優先探索","深さ優先探索","ミニマックス法"]',
   0, '[0]', 'single',
   '{"asked":"実際のコストと推定コスト（ヒューリスティック関数）の両方を使って最短経路を探す探索アルゴリズムを選ぶ問題。","point":"『実際のコスト＋ゴールまでの推定コストの両方を使って探す』と出たら、A*探索。","why_asked":"幅優先探索・深さ優先探索は『やみくもに』調べる素朴な探索だが、A*探索は『どちらに進むと近道か』という見積もり（ヒューリスティック関数）を使って賢く探索を絞り込む点が試験で問われる。","kid":"知らない街で目的地に向かうとき、地図アプリが『ここまでの距離』と『ゴールまでのだいたいの距離』の両方を見て、一番効率の良さそうな道を選んでくれるイメージ。","terms":[["A*探索（エースター探索）","スタートからの実際のコストと、ゴールまでの推定コスト（ヒューリスティック関数）の両方を使って最短経路を探す探索アルゴリズム"],["ヒューリスティック関数","ゴールまでの残りのコストを、正確ではないがそれらしく見積もる関数"],["幅優先探索","スタートに近い場所から順に、しらみつぶしに調べていく探索方法"]],"eg":"知らない街で、地図アプリが『ここまで来た距離』と『ゴールまでのだいたいの距離』の両方を見て、一番効率の良さそうな道を選んでくれるイメージ。","think":"幅優先探索や深さ優先探索は、ゴールがどっちの方向にあるかを考えずに、決まった順番でしらみつぶしに調べる。A*探索はそれに加えて『ここからゴールまでだいたいこれくらいかかりそう』という見積もり（ヒューリスティック関数）を使い、有望な方向を優先して調べることで、無駄な探索を減らす。","vs":"幅優先探索・深さ優先探索は推定コストを使わない素朴な探索順序の違いにすぎない。ミニマックス法は2人が交互に手を選ぶゲームの評価方針で、最短経路を探す探索とは目的が異なる。","usecase":"カーナビやゲームのキャラクターの移動経路探索など、実際に効率の良い最短経路を求めたい場面で使われる。","opt":["正解。スタートからの実際のコストと、ゴールまでの推定コスト（ヒューリスティック関数）の両方を使って、効率よく最短経路を探す。","近い場所から順にしらみつぶしに調べる探索方法で、ゴールまでの推定コストを使って探索を絞り込む工夫は無い。","行けるところまで一本道を掘り下げてから戻る探索方法で、こちらも推定コストを使って絞り込む工夫は無い。","2人が交互に手を選ぶゲームで、自分は最大・相手は最小を選ぶと仮定して評価する探索の考え方で、最短経路を探すための探索ではない。"]}'),

  ('g-kentei-q61', '2. 人工知能をめぐる動向',
   'エキスパートシステムで、既に分かっている事実にルールを次々と適用し、新しい事実を導き出しながらゴールに向かう推論の進め方はどれか。',
   NULL::text,
   '["前向き推論","後ろ向き推論","ミニマックス法","深さ優先探索"]',
   0, '[0]', 'single',
   '{"asked":"分かっている事実にルールを次々と適用して結論を導く、エキスパートシステムの推論の進め方を選ぶ問題。","point":"『事実からルールを適用して、ゴールに向かって進む』なら前向き推論。『先に結論を仮定して、事実で裏付けを逆向きにたどる』なら後ろ向き推論。","why_asked":"MYCINなどのエキスパートシステムは『IF-THENルール』の集まりに対して、どちらの向きで推論を進めるかで前向き推論・後ろ向き推論に分かれる。この向きの違いが定番の出題。","kid":"前向き推論は、持っている手がかりを1つずつ足していって答えにたどり着く進め方。後ろ向き推論は、先に『たぶんこれが答え』と決めてから、その裏付けを探しに戻る進め方。","terms":[["前向き推論","既に分かっている事実にIF-THENルールを次々と適用し、新しい事実を導き出しながらゴールに向かう推論"],["後ろ向き推論","先に結論（仮説）を立て、それを裏付ける事実があるかを逆向きにたどって確かめる推論"],["IF-THENルール","『もし〜ならば、〜である』という形で知識を表現する、エキスパートシステムの基本的なルールの書き方"]],"eg":"前向き推論は、集めた証拠を1つずつ積み上げて犯人にたどり着く進め方。後ろ向き推論は、先に『犯人はこの人だ』と仮定して、その裏付けとなる証拠を探しに戻る進め方。","think":"どちらもIF-THENルールを使うが、進む向きが逆。前向き推論は『今分かっている事実→ルールを適用→新しい事実→…→ゴール』と手前から積み上げていく。後ろ向き推論は『ゴール（仮説）→それを裏付けるにはどんな事実が要るか→事実を確認』とゴールから逆向きにたどる。","vs":"ミニマックス法は2人のゲームでの評価方針、深さ優先探索は探索木の掘り下げ順序で、どちらもIF-THENルールを使った推論の向きの話ではない。","usecase":"MYCINのような医療診断のエキスパートシステムで、症状（事実）から病名を導く（前向き）か、疑われる病名（仮説）を裏付ける症状を確認しに行く（後ろ向き）かの設計判断に関わる。","opt":["正解。既に分かっている事実にルールを次々と適用し、新しい事実を導き出しながらゴールに向かう推論の進め方。","まず結論（仮説）を立ててから、それを裏付ける事実があるかを逆向きにたどって確かめる推論の進め方で、事実からゴールへ向かう進め方とは逆。","2人が交互に手を選ぶゲームで、自分は最大・相手は最小を選ぶと仮定して評価する探索の考え方で、事実からルールを適用していく推論の仕組みではない。","行けるところまで一本道を掘り下げてから戻る探索方法で、事実にルールを適用して結論を導く推論の仕組みではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
